using System;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Windows.Forms;
namespace OpenAntiLag {
 public sealed class StatisticsPage:ToolPage {
  readonly ComboBox process;readonly NumericUpDown duration,interval;readonly PerformanceMonitor monitor=new PerformanceMonitor();readonly HistoryGraph graph=new HistoryGraph();BenchmarkResult before,after;readonly Label live;readonly NetworkMonitor network;
  public StatisticsPage(bool preview,NetworkMonitor network):base("Статистика",preview){this.network=network;Name="statisticsPage";Note("CPU/RAM измеряются штатными API. CPU процесса нормирован на все логические CPU; RAM процесса — Working Set. FPS, 1% Low, frametime и GPU-загрузка не заявлены: проверенный внешний сборщик не подключён. Нет DLL/оверлея и вмешательства в античит.");process=Choice(330);process.Items.Add("Только общая CPU/RAM");process.SelectedIndex=0;duration=Number(5,3600,120);interval=Number(1,60,2);Row(ActionButton("Обновить процессы",async ct=>{var processes=await Task.Run(()=>GameConnections.Processes(),ct);process.Items.Clear();process.Items.Add("Только общая CPU/RAM");foreach(var p in processes.Where(p=>!GameConnections.ProtectedName(p.Name)))process.Items.Add(p);process.SelectedIndex=0;}),process);Row(Caption("Длительность, с"),duration,Caption("Интервал, с"),interval);Row(ActionButton("Измерение «до»",ct=>Measure(false,ct)),ActionButton("Измерение «после»",ct=>Measure(true,ct)),ActionButton("Сравнить",ct=>{ShowText(BenchmarkComparison.Compare(before,after));return Task.FromResult(0);}));Row(ActionButton("Экспорт производительности",ct=>{string path=ExportPath("CPU/RAM");if(path!=null)PerformanceMonitor.Export(path,monitor.Snapshot());return Task.FromResult(0);}),ActionButton("Сводка сети",async ct=>{var all=await Task.Run(()=>NetworkAdapters.Read(),ct);ShowText(NetworkDiagnostics.Analyze(network.History.Snapshot(),all,100,20)+"\r\n\r\n"+String.Join("\r\n",all.Select(NetworkAdapters.Describe)));}));live=Note("Данных CPU/RAM пока нет.");Controls.Add(graph);graph.BringToFront();AdapterSnapshot[] previous=null;DateTime previousTime=DateTime.UtcNow;
   monitor.Sample+=sample=>OnUi(delegate{live.Text="CPU "+(sample.CpuPercent.HasValue?sample.CpuPercent.Value.ToString("0.0"):"—")+"% · процесс "+(sample.ProcessCpuPercent.HasValue?sample.ProcessCpuPercent.Value.ToString("0.0"):"—")+"% · RAM доступно "+(sample.RamAvailable/1024/1024)+" / "+(sample.RamTotal/1024/1024)+" МБ · Working Set "+(sample.ProcessWorkingSet.HasValue?(sample.ProcessWorkingSet.Value/1024/1024).ToString():"—")+" МБ";graph.SetValues(monitor.Snapshot().Where(s=>s.CpuPercent.HasValue).Select(s=>s.CpuPercent.Value));try{var adapters=NetworkAdapters.Read();double seconds=(sample.Utc-previousTime).TotalSeconds;if(previous!=null&&seconds>0)foreach(var adapter in adapters.Where(a=>a.State=="Up")){var old=previous.FirstOrDefault(a=>a.Id==adapter.Id);if(old!=null&&adapter.Received>=old.Received&&adapter.Sent>=old.Sent)Log(sample.Utc.ToLocalTime().ToString("HH:mm:ss")+" · "+adapter.Name+" · RX "+((adapter.Received-old.Received)/seconds/1024).ToString("0.0")+" КБ/с · TX "+((adapter.Sent-old.Sent)/seconds/1024).ToString("0.0")+" КБ/с (весь адаптер, не игра)");}previous=adapters;previousTime=sample.Utc;}catch(Exception){Log("Счётчики адаптера недоступны");}});
  }
  async Task Measure(bool second,CancellationToken ct){int pid=process.SelectedItem is GameProcess?((GameProcess)process.SelectedItem).Id:0;int seconds=(int)duration.Value,milliseconds=(int)interval.Value*1000;DateTime start=DateTime.UtcNow;await monitor.Run(pid,seconds,milliseconds,ct);if(!monitor.Completed)throw new InvalidOperationException("Измерение не завершено");var result=new BenchmarkResult {Label=second?"После":"До",Duration=seconds,Interval=milliseconds,ProcessId=pid,Samples=monitor.Snapshot().Where(s=>s.Utc>=start&&s.ProcessId==pid).ToArray()};if(second)after=result;else before=result;Log("Измерение «"+result.Label+"»: "+result.Samples.Length+" отсчётов. Сравнение требует одинаковой нагрузки; совпадение изменений не доказывает причинную связь.");}
 }
}
